function winChart() {
  const pts = SCENS.map(s => [s[1], s[2]]).sort((a, b) => a[0] - b[0]), X = m => 40 + (m - 3) / 10 * 500, Y = w => 150 - w / 50 * 130, cur = estTotals().m;
  return `<svg viewBox="0 0 560 175" style="width:100%;display:block" role="img" aria-label="Estimated win probability falls as margin rises">${[0, 25, 50].map(w => `<line x1="40" x2="540" y1="${Y(w)}" y2="${Y(w)}" style="stroke:var(--line-2)"/><text x="34" y="${Y(w) + 4}" text-anchor="end" style="font:10px var(--f-mono);fill:var(--muted)">${w}%</text>`).join('')}<polyline points="${pts.map(p => X(p[0]) + ',' + Y(p[1])).join(' ')}" style="fill:none;stroke:var(--pack);stroke-width:2"/>${pts.map(p => `<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="4" style="fill:var(--pack)"/><text x="${X(p[0])}" y="168" text-anchor="middle" style="font:10px var(--f-mono);fill:var(--muted)">${p[0]}%</text>`).join('')}<line x1="${X(cur)}" x2="${X(cur)}" y1="15" y2="150" style="stroke:var(--brand);stroke-dasharray:4 3"/><text x="${X(cur) + 4}" y="24" style="font:600 10.5px var(--f-mono);fill:var(--brand)">current ${cur}%</text></svg>`;
}
function cashFlow() {
  if (!can('envB')) return '<div class="note warn"><div>Cash flow uses envelope B figures.</div></div>';
  const e = estTotals(), N = 30, S_ = t => 1 / (1 + Math.exp(-(t - N * 0.55) / (N * 0.13))), s0 = S_(0), s1 = S_(N), cum = t => (S_(t) - s0) / (s1 - s0);
  const ms = [0.1, 0.25, 0.5, 0.75, 1]; const pos = []; let rec = 0, done = 0, min = 0, minM = 0;
  for (let t = 0; t <= N; t++) { while (done < ms.length && cum(t) >= ms[done] - 1e-9) { rec += e.price * 0.08; done++; } const c = rec - e.cost * cum(t); pos.push(c); if (c < min) { min = c; minM = t; } }
  const lo = Math.min(...pos), hi = Math.max(...pos, 1), X = t => 40 + t / N * 510, Y = v => 15 + (hi - v) / (hi - lo) * 140;
  return `<div class="panel"><div class="ph"><h3>Cash position during construction</h3><span class="sub">HAM: 40% of BPC as 5 milestone payments; annuities start after COD</span></div><div class="pb"><svg viewBox="0 0 570 185" style="width:100%;display:block" role="img" aria-label="Cumulative cash position, lowest ${fmtN(min, 0)} crore at month ${minM}"><line x1="40" x2="550" y1="${Y(0)}" y2="${Y(0)}" style="stroke:var(--ink-2)"/><text x="34" y="${Y(0) + 4}" text-anchor="end" style="font:10px var(--f-mono);fill:var(--muted)">0</text><polygon points="${X(0)},${Y(0)} ${pos.map((v, t) => X(t) + ',' + Y(v)).join(' ')} ${X(N)},${Y(0)}" style="fill:var(--bad-soft)"/><polyline points="${pos.map((v, t) => X(t) + ',' + Y(v)).join(' ')}" style="fill:none;stroke:var(--bad);stroke-width:2"/><circle cx="${X(minM)}" cy="${Y(min)}" r="4" style="fill:var(--bad)"/><text x="${X(minM)}" y="${Y(min) + 16}" text-anchor="middle" style="font:600 10.5px var(--f-mono);fill:var(--ink)">${cr(min, 0)} · M${minM}</text>${[0, 10, 20, 30].map(t => `<text x="${X(t)}" y="180" text-anchor="middle" style="font:10px var(--f-mono);fill:var(--muted)">M${t}</text>`).join('')}</svg>
   <p class="sub">Peak funding requirement <b>${cr(-min)}</b> at month ${minM}. This is what the “financing during construction” adder pays for; check it against the adder in Escalation & market.</p></div></div>`;
}

const TABV = { brief: tBrief, docs: mDocs, reqs: tReqs, basis: tBasis, elig: tElig, risks: tRisks, clar: tClar, g1: tG1, eng: tEng, proc: tProc, est: tEst, pstruct: mPStruct, pown: mPOwn, pdraft: mPDraft, pcomp: mPComp, pann: mPAnn, pcomm: mPComm, psub: mPSub };
